/**
 * Freeze ISO 3166-1 alpha-2 / alpha-3 codes into src/lib/countries.data.ts.
 * i18n-iso-countries stays a devDependency so locale JSON is not shipped.
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import countries from "i18n-iso-countries";

const alpha2 = Object.keys(countries.getAlpha2Codes()).sort();
const alpha3 = countries.getAlpha3Codes();
const alpha3Keys = Object.keys(alpha3).sort();

const lines = [
  "/** Generated by scripts/gen-countries.mjs. Do not edit by hand. */",
  "export const COUNTRY_CODES = [",
  ...alpha2.map((code) => `  "${code}",`),
  "] as const;",
  "",
  "export const ALPHA3_TO_ALPHA2: Record<string, string> = {",
  ...alpha3Keys.map((key) => `  ${JSON.stringify(key)}: ${JSON.stringify(alpha3[key])},`),
  "};",
  "",
];

const out = join(dirname(fileURLToPath(import.meta.url)), "..", "src/lib/countries.data.ts");
writeFileSync(out, lines.join("\n"));
console.log(`[gen-countries] ${alpha2.length} alpha-2 codes, ${alpha3Keys.length} alpha-3 codes`);
